async function main() {
  console.log('=== AAP Verification Demo ===');
  console.log('Marker:', MARKER);
  console.log('');

  // Start the server as a child process
  console.log('Starting AAP server...');
  const serverProcess = spawn('node', ['server.js'], {
    stdio: ['pipe', 'pipe', 'pipe']
  });

  // Capture server output
  serverProcess.stdout.on('data', (data) => {
    const output = data.toString();
    console.log('SERVER:', output.trim());
  });

  serverProcess.stderr.on('data', (data) => {
    console.error('SERVER ERROR:', data.toString());
  });

  // Wait for server to start
  await new Promise(resolve => setTimeout(resolve, 1000));

  console.log('');
  console.log('Running client verification...');
  console.log('');

  let result;
  try {
    result = await runVerification(`ws://localhost:${PORT}${PATH}`, DETERMINISTIC_SEED);
  } catch (err) {
    console.error('Verification failed:', err.message);
    result = {
      verified: false,
      error: err.message,
      timestamp: new Date().toISOString()
    };
  }

  // Stop the server
  serverProcess.kill();

  // Prepare verification summary
  const summary = {
    marker: MARKER,
    serverLog: 'server-started',
    resultFile: 'verification-summary.json',
    verification: {
      verified: result.verified || false,
      correctCount: result.correctCount || 0,
      totalChallenges: result.totalChallenges || 7,
      sessionToken: result.sessionToken || null
    },
    identity: result.identity || {
      publicKey: '',
      publicId: ''
    },
    proofPayload: result.proofForInspection || null,
    timestamp: new Date().toISOString(),
    serverUrl: `ws://localhost:${PORT}${PATH}`,
    seedUsed: DETERMINISTIC_SEED
  };

  // Write summary to file
  const summaryPath = 'verification-summary.json';
  writeFileSync(summaryPath, JSON.stringify(summary, null, 2));
  console.log('');
  console.log('Verification summary written to:', summaryPath);
  console.log('');

  // Print summary for inspection
  console.log('=== Verification Summary ===');
  console.log(JSON.stringify(summary, null, 2));
  console.log('');

  // Print proof payload for easy inspection
  if (summary.proofPayload) {
    console.log('=== Signed Proof Payload (for inspection) ===');
    console.log(JSON.stringify(summary.proofPayload, null, 2));
    console.log('');
  }

  // Exit with appropriate code
  process.exit(result.verified ? 0 : 1);
}

main().catch(err => {
  console.error('Fatal error:', err);
  process.exit(1);
});
RUNEOF
